Method.Implementation:
s data("RECTITLE")=$p($$$getTagX(.handle,"Tbca"),"\n",1)
;s data("FILENAME")=$p(data("ORIGNAME"),".")_"_metadata"

s recType=##class(User.MARC).getTagX(.handle,"970b")
if recType="DATA" {  
  s data("FILENAME")=$p(data("ORIGNAME"),".")_"_metadata"
  s data("BASE64HTML")=##class(%SYSTEM.Encryption).Base64Encode($zcvt(data("RECTITLE")_"<br><br>"_data("NOW"),"O","UTF8"))
  s data("METATEXT")=##class(rep.zf.tf).stripHtmlTags(data("RECTITLE"))_$$$CRLF_$$$CRLF_data("NOW")
  s data("BASE64TEXT")=##class(%SYSTEM.Encryption).Base64Encode($zcvt(data("METATEXT"),"O","UTF8"))
}
elseif recType="X" {
  s data("FILENAME")=$p(data("ORIGNAME"),".")_"_info"
  s data("RECTITLE")=data("RECTITLE")_" pod licencí "_$g(array("licencecc"))
  s text="preprint (nerecenzovaný dokument): "
  s data("BASE64HTML")=##class(%SYSTEM.Encryption).Base64Encode($zcvt(text_data("RECTITLE")_"<br><br>"_data("NOW"),"O","UTF8"))
  s data("METATEXT")=text_##class(rep.zf.tf).stripHtmlTags(data("RECTITLE"))_$$$CRLF_$$$CRLF_data("NOW")
  s data("BASE64TEXT")=##class(%SYSTEM.Encryption).Base64Encode($zcvt(data("METATEXT"),"O","UTF8"))
} else {
  s data("FILENAME")=""
}
